window.U1_PREVIEW_RECORDS={"apwh-u1-angkor-khmer-hydraulic-state": {"id": "apwh-u1-angkor-khmer-hydraulic-state", "examSkills": ["Causation", "Comparison"], "locationNumber": "7", "mainEventKey": "world-event-7-0", "title": "Angkor's Hydraulic State", "dateLabel": "802–1431", "startYear": 802, "endYear": 1431, "summary": "Khmer rulers organized reservoirs, canals, and labor around Angkor to manage water and support intensive rice agriculture.", "significance": "Control of water and labor produced agricultural surpluses that sustained Angkor, financed monumental building, and strengthened royal authority.", "keyPeople": [{"name": "Jayavarman II", "role": "Established the Khmer imperial tradition that later rulers expanded around Angkor."}], "keyTerms": [{"term": "baray", "explanation": "A large Khmer reservoir used within Angkorian systems of water storage and management."}, {"term": "hydraulic state", "explanation": "A state whose authority and resources are closely connected to organizing large water-control works."}], "evidence": ["Angkor contained extensive reservoirs and canals associated with managing seasonal water supplies.", "Rice surpluses supported a dense capital and the labor required for temples and public works."], "examConnection": "Use Angkor to explain how rulers in South and Southeast Asia connected environmental management, agricultural surplus, and state building.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.3"}, "topicCodes": ["1.3", "1.7"], "themeIds": ["GOV", "ECN", "TEC"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-angkor-hindu-buddhist-legitimation"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-angkor-hindu-buddhist-legitimation": "Agricultural surplus and organized labor helped Khmer rulers finance monumental religious patronage."}, "unit": 1}, "apwh-u1-baghdad-merchant-ulema-network": {"id": "apwh-u1-baghdad-merchant-ulema-network", "examSkills": ["Causation", "Comparison"], "locationNumber": "3", "mainEventKey": "world-event-3-0", "title": "Merchants, Ulama, and Islamic Trade", "dateLabel": "1000–1450", "startYear": 1000, "endYear": 1450, "summary": "Merchants and religious scholars linked commercial practice, law, and trust across the Islamic world.", "significance": "Shared legal ideas and respect for commerce helped strangers transact across long distances despite political fragmentation after Abbasid decline.", "keyPeople": [{"name": "Muslim merchants", "role": "Carried goods, commercial practices, and religious traditions through interconnected cities and ports."}], "keyTerms": [{"term": "sharia", "explanation": "Islamic moral and legal traditions that included rules relevant to contracts, property, and exchange."}, {"term": "diaspora", "explanation": "A community living away from its place of origin while maintaining social and commercial connections."}], "evidence": ["Merchants held respected positions in many Muslim societies and supported mosques, schools, and charitable institutions.", "Ulama provided teaching and legal interpretation across states whose rulers and dynasties changed over time."], "examConnection": "Use this network to explain how a shared religious and legal culture maintained continuity across politically divided Islamic states.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.2"}, "topicCodes": ["1.2", "1.7"], "themeIds": ["ECN", "CDI"], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-baghdad-abbasid-knowledge-hub", "apwh-u1-delhi-bhakti-sufi-devotion", "apwh-u1-timbuktu-islamic-learning-griots"], "connectionNotes": {"apwh-u1-baghdad-abbasid-knowledge-hub": "Scholarship, religious learning, and trusted urban networks reinforced Baghdad's wider role in the Islamic world.", "apwh-u1-delhi-bhakti-sufi-devotion": "Mobile Muslim teachers and shared religious networks help compare the spread and local adaptation of Islam across regions.", "apwh-u1-timbuktu-islamic-learning-griots": "Commercial and scholarly networks carried Islamic institutions while local societies retained distinct cultural practices."}, "unit": 1}, "apwh-u1-cusco-ayllu-mita-labor": {"id": "apwh-u1-cusco-ayllu-mita-labor", "examSkills": ["Causation", "Comparison"], "locationNumber": "50", "mainEventKey": "world-event-50-0", "title": "Ayllu, Mit'a, and State Labor", "dateLabel": "1438–1450", "startYear": 1438, "endYear": 1450, "summary": "Inca rulers organized ayllu communities through rotating mit'a labor obligations rather than relying on a money tax.", "significance": "The mit'a converted community labor into roads, terraces, armies, storehouses, and public works that expanded imperial capacity across the Andes.", "keyPeople": [{"name": "ayllu leaders", "role": "Coordinated kin-based communities and helped allocate households for rotating state labor obligations."}], "keyTerms": [{"term": "ayllu", "explanation": "An Andean kin-based community that shared land, obligations, and mutual support."}, {"term": "mit'a", "explanation": "A rotating labor obligation through which communities supplied workers to the Inca state."}], "evidence": ["Households supplied labor for farming state lands, military service, construction, and transport.", "The state redistributed stored goods during campaigns, ceremonies, and periods of local need."], "examConnection": "Use ayllu and mit'a to explain how the Inca mobilized labor and compare their system with tribute or tax collection in other empires.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["SIO", "GOV", "ECN"], "causeStudyPointIds": ["apwh-u1-cusco-pachacuti-tawantinsuyu"], "effectStudyPointIds": ["apwh-u1-cusco-roads-quipu-administration"], "relatedStudyPointIds": ["apwh-u1-tenochtitlan-triple-alliance-tribute", "apwh-u1-tenochtitlan-chinampas-urban-state"], "connectionNotes": {"apwh-u1-cusco-pachacuti-tawantinsuyu": "Rapid territorial expansion required Inca rulers to organize local ayllus and rotate labor obligations across a much larger state.", "apwh-u1-cusco-roads-quipu-administration": "Mobilized mit'a labor built and maintained roads, while officials used quipu records to track resources and obligations.", "apwh-u1-tenochtitlan-triple-alliance-tribute": "The Aztec tribute system and the Inca mit'a system extracted resources differently: one emphasized subject payments, while the other mobilized labor through communities.", "apwh-u1-tenochtitlan-chinampas-urban-state": "Both states adapted difficult environments through organized labor, although chinampas intensified lake agriculture while Inca communities managed highland production and terraces."}, "unit": 1}, "apwh-u1-hangzhou-confucian-bureaucracy-culture": {"id": "apwh-u1-hangzhou-confucian-bureaucracy-culture", "locationNumber": "1", "mainEventKey": "world-event-1-0", "sequence": 1, "title": "Confucian Government, Civil-Service Exams, and Social Order", "dateLabel": "960–1279", "startYear": 960, "endYear": 1279, "topicCodes": ["1.1", "1.7"], "themeIds": ["GOV", "CDI", "SIO"], "examSkills": ["Causation", "Comparison"], "summary": "Song rulers relied on an expanding civil-service bureaucracy and Confucian learning to govern, while examination access favored families able to finance education.", "significance": "Exams linked state service to literary learning without eliminating social inequality; Neo-Confucian ideas also reinforced hierarchical relationships.", "keyTerms": [{"term": "civil-service examinations", "explanation": "Competitive tests of classical learning used to recruit officials, not universal or socially equal access to power."}, {"term": "Neo-Confucianism", "explanation": "A renewed Confucian intellectual tradition that incorporated responses to Buddhist and Daoist thought while emphasizing moral order."}], "evidence": ["Song governments expanded the role of scholar-officials recruited through examinations in Confucian texts.", "Education costs and family resources shaped access; patriarchal norms continued alongside commercial and urban growth."], "examConnection": "Explain how a state maintained authority through trained officials and shared ideas, then compare formal examination access with actual social advantages.", "keyPeople": [{"name": "Scholar-officials", "role": "Administered the state and connected classical learning with government service."}], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-hangzhou-song-commercial-revolution"], "connectionNotes": {"apwh-u1-hangzhou-song-commercial-revolution": "Compare the institutions that governed Song society with the expanding markets those institutions taxed and administered; commercial growth did not automatically eliminate Confucian social hierarchy."}, "source": {"id": "teacher-created-2026-10-25", "locator": "Teacher-authored synthesis; College Board CED and linked sources, not an official College Board item or a quotation from AMSCO."}, "authorship": "teacher-created", "sourceUrls": ["https://apcentral.collegeboard.org/media/pdf/ap-world-history-modern-course-and-exam-description-effective-fall-2026.pdf"], "regionLabel": "Song China · Hangzhou is a representative urban and administrative anchor", "unit": 1}, "apwh-u2-malacca-merchant-diasporas-spread-islam": {"id": "apwh-u2-malacca-merchant-diasporas-spread-islam", "locationNumber": "2", "mainEventKey": "world-event-2-1", "title": "Merchant Diasporas and the Spread of Islam", "dateLabel": "c. 1400–1450", "startYear": 1400, "endYear": 1450, "summary": "Muslim merchants who remained in Southeast Asian ports formed communities, married locally, and helped Islam gain influence without military conquest.", "significance": "Diaspora settlement turned waiting time and commercial trust into long-term cultural change while local societies adapted Islam to existing traditions.", "keyPeople": [{"name": "Muslim merchant communities", "role": "Maintained commercial and religious ties while establishing households and institutions in Southeast Asian ports."}], "keyTerms": [{"term": "diaspora", "explanation": "A community living away from its place of origin while preserving social, cultural, or commercial connections."}, {"term": "syncretism", "explanation": "The combination or adaptation of elements drawn from different cultural and religious traditions."}], "evidence": ["Merchants often stayed in ports for months while waiting for monsoon winds and sometimes established permanent households.", "Islam spread through commercial relationships, intermarriage, and local rulers rather than a single campaign of conquest."], "examConnection": "Use Malacca to explain how exchange caused cultural change, while noting that adoption remained selective and local traditions continued.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.5"}, "sequence": 3, "topicCodes": ["2.3", "2.5"], "themeIds": ["CDI", "SIO"], "examSkills": ["Causation", "CCOT"], "causeStudyPointIds": ["apwh-u2-malacca-strategic-port-state"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-kilwa-swahili-cultural-synthesis"], "connectionNotes": {"apwh-u2-malacca-strategic-port-state": "A protected and heavily visited port encouraged foreign merchants to reside, marry, and establish religious communities.", "apwh-u2-kilwa-swahili-cultural-synthesis": "Resident Muslim merchants contributed to locally distinct forms of Islamic cultural change in Southeast Asia and the Swahili Coast."}, "unit": 2}, "apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce": {"id": "apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce", "locationNumber": "85", "mainEventKey": "world-event-85-0", "title": "Swahili City-States and Indian Ocean Commerce", "dateLabel": "1000–1450", "startYear": 1000, "endYear": 1450, "summary": "Kilwa and other Swahili city-states connected East African producers with merchants from Arabia, Persia, India, and China.", "significance": "Commercial access supported autonomous coastal cities whose rulers and merchants accumulated wealth without controlling a single territorial empire.", "keyPeople": [{"name": "Swahili merchant elites", "role": "Managed coastal trade, maintained overseas relationships, and sponsored urban construction and Islamic institutions."}], "keyTerms": [{"term": "city-state", "explanation": "An independent political community centered on a city and its surrounding territory."}, {"term": "Indian Ocean network", "explanation": "The maritime exchange system connecting East Africa, Southwest Asia, South Asia, Southeast Asia, and East Asia."}], "evidence": ["Kilwa exported African goods and imported Indian textiles, Chinese ceramics, and products from Southwest Asia.", "Commercial wealth supported coral-stone houses and mosques in coastal cities."], "examConnection": "Compare Swahili city-states with Malacca to show how maritime exchange supported different forms of port-based political power.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 1, "topicCodes": ["2.3", "2.7"], "themeIds": ["ECN", "GOV"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-kilwa-gold-ivory-regional-specialization", "apwh-u2-kilwa-swahili-cultural-synthesis"], "relatedStudyPointIds": ["apwh-u2-malacca-strategic-port-state"], "connectionNotes": {"apwh-u2-kilwa-gold-ivory-regional-specialization": "Demand from Indian Ocean merchants rewarded coastal access to inland gold, ivory, and other specialized exports.", "apwh-u2-kilwa-swahili-cultural-synthesis": "Long-term commercial contact joined Bantu-speaking coastal societies with Islamic and Arabic cultural influences.", "apwh-u2-malacca-strategic-port-state": "Kilwa and Malacca both converted strategic access to maritime exchange into urban wealth and political power."}, "unit": 2}, "apwh-u2-kilwa-crop-diffusion-environments": {"id": "apwh-u2-kilwa-crop-diffusion-environments", "locationNumber": "85", "mainEventKey": "world-event-85-0", "sequence": 4, "title": "Crop Diffusion, Population, and Environmental Change", "dateLabel": "c. 1200–1450", "startYear": 1200, "endYear": 1450, "topicCodes": ["2.3", "2.6", "2.7"], "themeIds": ["ENV", "ECN"], "examSkills": ["Causation", "Comparison"], "summary": "Exchange networks spread useful crops as well as pathogens; crops already introduced before 1200 continued to reshape population and land use during the course period.", "significance": "The movement of plants changed food supplies and settlement patterns, but effects depended on local environments and cultivation choices.", "keyTerms": [{"term": "crop diffusion", "explanation": "The movement and local adoption of cultivated plants across regions."}, {"term": "Champa rice", "explanation": "Early-ripening rice associated with Champa and adopted in China before 1200, with lasting effects on farming and food supply."}], "evidence": ["Bananas of Southeast Asian origin spread into Africa through networks connected to the Indian Ocean; adoption supported cultivation and settlement in suitable regions.", "Champa rice spread from Vietnam to China before 1200; its continuing cultivation supported more intensive production, while new farmland and settlement altered landscapes."], "examConnection": "Trace crop movement, local adaptation, and demographic or environmental consequences; distinguish the earlier introduction of a crop from its effects in 1200–1450.", "keyPeople": [{"name": "Farmers, merchants, and migrants", "role": "Carried plants and agricultural knowledge and adapted them to local conditions."}], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-cairo-black-death-demographic-change"], "connectionNotes": {"apwh-u2-cairo-black-death-demographic-change": "Compare different biological consequences of connected networks: crop adoption could support food production and settlement, while epidemic pathogens caused mortality and disruption."}, "source": {"id": "teacher-created-2026-10-25", "locator": "Teacher-authored synthesis; College Board CED and linked sources, not an official College Board item or a quotation from AMSCO."}, "authorship": "teacher-created", "sourceUrls": ["https://apcentral.collegeboard.org/media/pdf/ap-world-history-modern-course-and-exam-description-effective-fall-2026.pdf"], "regionLabel": "Indian Ocean and connected regions · Southeast Asia, East Africa, and China; Kilwa is one network anchor, not the site of every transfer", "unit": 2}, "apwh-u3-ming-qing-civil-service-continuity": {"id": "apwh-u3-ming-qing-civil-service-continuity", "locationNumber": "5", "empire": "Ming/Qing", "lens": "Administration", "mainEventKey": "world-event-5-0", "title": "Civil-Service Continuity under Ming and Qing", "dateLabel": "1368–1750", "startYear": 1368, "endYear": 1750, "summary": "Ming rulers restored schools, examinations, and scholar-official government after Yuan rule, and Qing emperors retained those institutions to administer China.", "significance": "Civil-service continuity supplied trained officials and linked both dynasties to Confucian political expectations, even though Manchu rulers also preserved separate conquest institutions.", "keyPeople": [{"name": "scholar-gentry", "role": "Educated elites who prepared for examinations, staffed government offices, and connected imperial policy with local society."}], "keyTerms": [{"term": "civil-service examination", "explanation": "A competitive test centered on Confucian learning that selected candidates for imperial office."}, {"term": "Confucian classics", "explanation": "Canonical texts studied by examination candidates and used to define the moral and political learning expected of officials."}], "evidence": ["The Ming restored examination schools and rebuilt a Confucian bureaucracy weakened under the Yuan.", "Qing emperors continued the examination system and employed Chinese scholar-officials across the civil administration."], "examConnection": "Use the examination system as continuity evidence while qualifying the claim: Qing rulers kept Chinese civil administration alongside Manchu banners and ethnic privileges.", "source": {"id": "amsco-apwh-u3", "locator": "AMSCO AP World History, Unit 3, Topics 3.2 and 3.4"}, "sequence": 2, "topicCodes": ["3.2", "3.4"], "themeIds": ["GOV", "SIO"], "examSkills": ["CCOT", "Comparison"], "causeStudyPointIds": ["apwh-u3-ming-qing-restoration-expansion"], "effectStudyPointIds": ["apwh-u3-ming-qing-manchu-confucian-ethnic-hierarchy"], "relatedStudyPointIds": ["apwh-u3-mughal-akbar-mansabdars-zamindars"], "connectionNotes": {"apwh-u3-ming-qing-restoration-expansion": "Ming restoration and Qing conquest both produced large territorial states whose rulers relied on the civil-service tradition to turn military control into routine administration.", "apwh-u3-ming-qing-manchu-confucian-ethnic-hierarchy": "Retaining Confucian officials helped Qing rulers claim Chinese dynastic legitimacy even as banner privileges and ethnic distinctions preserved a separate Manchu ruling identity.", "apwh-u3-mughal-akbar-mansabdars-zamindars": "Ming-Qing examinations and Mughal ranked service both connected local elites to imperial administration, although they recruited and rewarded officials differently."}, "unit": 3}, "apwh-u4-potosi-colonial-mita-labor": {"id": "apwh-u4-potosi-colonial-mita-labor", "locationNumber": "57", "mainEventKey": "world-event-57-0", "title": "Colonial Mit'a and Coerced Mining Labor", "dateLabel": "1573–1750", "startYear": 1573, "endYear": 1750, "summary": "Viceroy Francisco de Toledo reorganized a colonial mit'a in 1573 to draft Andean communities for labor at Potosí and Huancavelica.", "significance": "Colonial officials adapted an Inca labor obligation to Spanish mining, but the colonial mit'a was not identical to reciprocal service under Inca rule.", "keyPeople": [{"name": "Viceroy Francisco de Toledo", "role": "Reorganized communities and the colonial mit'a to supply workers to Potosí and Huancavelica."}], "keyTerms": [{"term": "mit'a", "explanation": "A rotating labor obligation adapted into a coercive colonial mining draft."}, {"term": "Huancavelica", "explanation": "The Andean mercury center supplying material essential to silver amalgamation."}], "evidence": ["Toledo's 1573 reforms required selected Andean communities to send rotating workers to Potosí.", "Workers also faced dangerous mercury production at Huancavelica and separation from households."], "examConnection": "Compare the colonial mit'a with its Inca precedent by identifying continuity in obligation and change in purpose, coercion, and benefit.", "source": {"id": "amsco-apwh-u4", "locator": "AMSCO AP World History, Unit 4, Topics 4.4 and 4.7"}, "sequence": 2, "topicCodes": ["4.4", "4.7"], "themeIds": ["SIO", "GOV", "ECN"], "examSkills": ["Comparison", "CCOT"], "causeStudyPointIds": ["apwh-u4-potosi-silver-mercury-boom"], "effectStudyPointIds": ["apwh-u4-potosi-global-silver-flows"], "relatedStudyPointIds": ["apwh-u4-salvador-african-chattel-slavery"], "connectionNotes": {"apwh-u4-potosi-silver-mercury-boom": "Rich silver deposits became far more profitable when mercury amalgamation raised usable output.", "apwh-u4-potosi-global-silver-flows": "Colonial officials expanded the mit'a to supply the labor needed for sustained silver production.", "apwh-u4-salvador-african-chattel-slavery": "Compare the colonial mit'a, adapted from an earlier Andean obligation, with racialized hereditary chattel slavery on Atlantic plantations."}, "unit": 4}, "apwh-u4-santo-domingo-columbian-exchange": {"id": "apwh-u4-santo-domingo-columbian-exchange", "locationNumber": "68", "mainEventKey": "world-event-68-0", "title": "The Columbian Exchange in the Caribbean", "dateLabel": "1492–1600", "startYear": 1492, "endYear": 1600, "summary": "Contact joined Caribbean, American, African, and Eurasian ecologies through transfers of crops, animals, people, and pathogens.", "significance": "The Columbian Exchange was bidirectional, but unequal power and biological vulnerability made its effects especially destructive for Taíno communities.", "keyPeople": [{"name": "Taíno communities", "role": "Experienced new animals, crops, diseases, labor demands, and colonial settlement after sustained Atlantic contact."}], "keyTerms": [{"term": "Columbian Exchange", "explanation": "The transfer of plants, animals, pathogens, and people between the Americas and Afro-Eurasia after 1492."}, {"term": "ecological transfer", "explanation": "The movement of organisms and environmental practices between separated ecosystems."}], "evidence": ["Europeans brought horses, cattle, pigs, wheat, and pathogens to Caribbean islands.", "American crops moved eastward while forced African migration added people and foodways to Atlantic societies."], "examConnection": "Compare transfers in both directions, then explain why bidirectional exchange did not mean equal effects on participating populations.", "source": {"id": "amsco-apwh-u4", "locator": "AMSCO AP World History, Unit 4, Topics 4.3 and 4.8"}, "sequence": 1, "topicCodes": ["4.3", "4.8"], "themeIds": ["ENV", "ECN", "SIO"], "examSkills": ["Comparison", "CCOT"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u4-santo-domingo-disease-demographic-collapse"], "relatedStudyPointIds": ["apwh-u4-manila-silver-asian-goods"], "connectionNotes": {"apwh-u4-santo-domingo-disease-demographic-collapse": "Transoceanic transfers brought unfamiliar pathogens into Caribbean populations.", "apwh-u4-manila-silver-asian-goods": "Compare the multidirectional Columbian Exchange with the silver-for-goods circuit that tied the Americas to Asian markets."}, "unit": 4}, "apwh-u1-hangzhou-song-commercial-revolution": {"id": "apwh-u1-hangzhou-song-commercial-revolution", "examSkills": ["Causation", "CCOT"], "locationNumber": "1", "mainEventKey": "world-event-1-0", "title": "Song Commercial Revolution", "dateLabel": "960–1279", "startYear": 960, "endYear": 1279, "summary": "Song rule encouraged production for markets, expanded cities, and connected regional exchange to Hangzhou.", "significance": "Commercialization made urban demand, specialized production, and long-distance exchange central features of Song prosperity and state revenue.", "keyPeople": [{"name": "Emperor Taizu", "role": "Founded the Song dynasty and established the political order in which commercial expansion developed."}], "keyTerms": [{"term": "commercialization", "explanation": "The growing production of goods for sale through markets rather than only for local subsistence."}, {"term": "tribute system", "explanation": "A diplomatic framework that also supported regulated exchange between China and neighboring states."}], "evidence": ["Song China supported a large urban population whose demand encouraged specialized craft and agricultural production.", "Hangzhou became a major political and commercial center linked to both inland and maritime exchange."], "examConnection": "Use this case to explain how state stability and expanding markets changed economic life in East Asia during the period c. 1200–1450.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.1"}, "topicCodes": ["1.1", "1.7"], "themeIds": ["ECN", "GOV"], "causeStudyPointIds": ["apwh-u1-hangzhou-grand-canal-urban-market"], "effectStudyPointIds": ["apwh-u1-hangzhou-paper-money-maritime-tools"], "relatedStudyPointIds": ["apwh-u1-hangzhou-confucian-bureaucracy-culture"], "connectionNotes": {"apwh-u1-hangzhou-grand-canal-urban-market": "Canal transport integrated productive regions with Hangzhou, supporting the urban demand and market exchange associated with Song commercialization.", "apwh-u1-hangzhou-paper-money-maritime-tools": "Expanding markets increased demand for scalable currency and safer long-distance navigation.", "apwh-u1-hangzhou-confucian-bureaucracy-culture": "Compare the institutions that governed Song society with the expanding markets those institutions taxed and administered; commercial growth did not automatically eliminate Confucian social hierarchy."}, "authorship": "teacher-revised", "revisionDate": "2026-10-25", "sourceNote": "Original AMSCO locator retained as legacy metadata, not a claim of verbatim verification. Revised wording is a teacher-authored synthesis; use revisionSources and the review ledger for verification.", "revisionSources": ["https://apcentral.collegeboard.org/media/pdf/ap-world-history-modern-course-and-exam-description-effective-fall-2026.pdf"], "unit": 1}, "apwh-u1-hangzhou-grand-canal-urban-market": {"id": "apwh-u1-hangzhou-grand-canal-urban-market", "examSkills": ["Causation"], "locationNumber": "1", "mainEventKey": "world-event-1-0", "title": "Grand Canal and the Hangzhou Market", "dateLabel": "1000–1279", "startYear": 1000, "endYear": 1279, "summary": "The Grand Canal carried grain and goods toward Hangzhou and helped sustain a large southern urban market.", "significance": "Canal transport joined productive regions to consumers and officials, allowing the Song state to provision cities and collect resources across its territory.", "keyPeople": [{"name": "Song transport officials", "role": "Managed canal shipments and the movement of tax grain toward administrative and urban centers."}], "keyTerms": [{"term": "Grand Canal", "explanation": "The inland waterway that linked northern and southern Chinese economic regions."}, {"term": "urbanization", "explanation": "The growth of cities as centers of administration, consumption, production, and exchange."}], "evidence": ["Hangzhou stood near the southern end of the Grand Canal and received goods from a broad internal market.", "Reliable water transport moved bulky grain more efficiently than overland shipment and supported large cities."], "examConnection": "Use the Grand Canal as evidence that government infrastructure could integrate regional economies and support urban growth in Song China.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.1"}, "topicCodes": ["1.1", "1.7"], "themeIds": ["ECN", "GOV", "TEC"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-hangzhou-song-commercial-revolution"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-hangzhou-song-commercial-revolution": "Canal transport integrated productive regions with Hangzhou, supporting the urban demand and market exchange associated with Song commercialization."}, "unit": 1}, "apwh-u1-hangzhou-paper-money-maritime-tools": {"id": "apwh-u1-hangzhou-paper-money-maritime-tools", "examSkills": ["Causation", "Comparison"], "locationNumber": "1", "mainEventKey": "world-event-1-0", "title": "Paper Money and Maritime Technology", "dateLabel": "1100–1279", "startYear": 1100, "endYear": 1279, "summary": "Paper money and improved navigation reduced transaction costs and helped Hangzhou connect with maritime Asia.", "significance": "Financial and navigational tools made trade easier to finance and safer to conduct, extending Song commercial influence beyond its internal market.", "keyPeople": [{"name": "Song merchants", "role": "Used paper currency, credit practices, and maritime knowledge to conduct exchange over longer distances."}], "keyTerms": [{"term": "paper money", "explanation": "Government-backed currency that reduced reliance on heavy strings of copper coins."}, {"term": "magnetic compass", "explanation": "A navigational instrument that helped mariners maintain direction beyond sight of land."}], "evidence": ["Song China expanded the use of paper currency in a highly monetized commercial economy.", "Chinese mariners used the compass and improved ship design to navigate regional sea routes."], "examConnection": "Use these innovations to explain how financial practices and navigation technologies increased the scale of exchange in and beyond East Asia.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.1"}, "topicCodes": ["1.1", "1.7"], "themeIds": ["ECN", "TEC"], "causeStudyPointIds": ["apwh-u1-hangzhou-song-commercial-revolution"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-hangzhou-song-commercial-revolution": "Expanding markets increased demand for scalable currency and safer long-distance navigation."}, "unit": 1}, "apwh-u1-angkor-hindu-buddhist-legitimation": {"id": "apwh-u1-angkor-hindu-buddhist-legitimation", "examSkills": ["Causation", "Comparison"], "locationNumber": "7", "mainEventKey": "world-event-7-0", "title": "Hindu and Buddhist Legitimation at Angkor", "dateLabel": "1113–1431", "startYear": 1113, "endYear": 1431, "summary": "Khmer rulers used Hindu and later Buddhist institutions and monuments to present kingship as sacred and protective.", "significance": "Religious adaptation let successive rulers claim continuity while changing traditions, tying political loyalty to temples, ritual, and royal patronage.", "keyPeople": [{"name": "Suryavarman II", "role": "Sponsored Angkor Wat and used monumental Hindu architecture to express royal authority."}], "keyTerms": [{"term": "Angkor Wat", "explanation": "A monumental temple complex first dedicated to Vishnu and associated with Khmer royal power."}, {"term": "Theravada Buddhism", "explanation": "A Buddhist tradition that became increasingly influential in mainland Southeast Asia."}], "evidence": ["Angkor Wat joined religious symbolism, royal patronage, and monumental labor in one political landscape.", "Khmer religious life shifted from strongly Hindu court traditions toward Buddhism without erasing Angkor as a sacred center."], "examConnection": "Use this transition to explain how Southeast Asian states adapted imported religions to legitimize rulers and maintain political continuity.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.3"}, "topicCodes": ["1.3", "1.7"], "themeIds": ["GOV", "CDI"], "causeStudyPointIds": ["apwh-u1-angkor-khmer-hydraulic-state"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-angkor-khmer-hydraulic-state": "Agricultural surplus and organized labor helped Khmer rulers finance monumental religious patronage."}, "unit": 1}, "apwh-u1-delhi-sultanate-state-building": {"id": "apwh-u1-delhi-sultanate-state-building", "examSkills": ["Comparison", "Causation"], "locationNumber": "6", "mainEventKey": "world-event-6-0", "title": "Delhi Sultanate State Building", "dateLabel": "1206–1450", "startYear": 1206, "endYear": 1450, "summary": "Turkic Muslim rulers governed from Delhi while ruling a large population that remained mainly Hindu.", "significance": "The sultanate created a durable Islamic state in northern India while relying on accommodation, military power, and existing local institutions.", "keyPeople": [{"name": "Raziyya", "role": "Ruled the Delhi Sultanate from 1236 to 1240 and demonstrated both the reach and limits of female sovereignty."}], "keyTerms": [{"term": "Delhi Sultanate", "explanation": "A sequence of Muslim-ruled dynasties governing much of northern India from Delhi."}, {"term": "jizya", "explanation": "A tax historically imposed by some Muslim governments on non-Muslim subjects."}], "evidence": ["A Muslim political minority governed territories whose population remained predominantly Hindu.", "The sultanate preserved many local social practices even as it introduced Persianate and Islamic political traditions."], "examConnection": "Use Delhi to explain how a religious minority could build a state by combining conquest with selective accommodation of local society.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.3"}, "topicCodes": ["1.3", "1.7"], "themeIds": ["GOV", "CDI"], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-delhi-bhakti-sufi-devotion", "apwh-u1-london-magna-carta-monarchy"], "connectionNotes": {"apwh-u1-delhi-bhakti-sufi-devotion": "Both developments show how Islamic institutions interacted with a predominantly Hindu South Asian society without erasing religious distinctions.", "apwh-u1-london-magna-carta-monarchy": "Both cases reveal negotiations between rulers and powerful groups, but Magna Carta formalized baronial constraints while Delhi sultans balanced minority rule with military and local political accommodation."}, "unit": 1}, "apwh-u1-delhi-bhakti-sufi-devotion": {"id": "apwh-u1-delhi-bhakti-sufi-devotion", "examSkills": ["Comparison", "CCOT"], "locationNumber": "6", "mainEventKey": "world-event-6-4", "title": "Bhakti and Sufi Devotional Traditions", "dateLabel": "1100–1450", "startYear": 1100, "endYear": 1450, "summary": "Bhakti teachers and Sufi mystics emphasized personal devotion and reached communities beyond formal religious elites.", "significance": "Devotional movements created shared practices and cultural exchange without eliminating the distinct institutions of Hinduism and Islam.", "keyPeople": [{"name": "Nizamuddin Auliya", "role": "A prominent Chishti Sufi teacher in Delhi whose community emphasized devotion, service, and spiritual instruction."}], "keyTerms": [{"term": "Bhakti", "explanation": "A Hindu devotional tradition emphasizing a direct and loving relationship with a chosen deity."}, {"term": "Sufism", "explanation": "Mystical Islamic practices that emphasized personal experience, discipline, and closeness to God."}], "evidence": ["Bhakti devotion could bypass some ritual and social barriers by stressing an individual's relationship with a deity.", "Sufi teachers formed communities that helped Islam take root through teaching and personal example."], "examConnection": "Use Bhakti and Sufism to explain cultural interaction in South Asia while avoiding the claim that the two religions simply merged.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.3"}, "topicCodes": ["1.3", "1.7"], "themeIds": ["CDI", "SIO"], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-delhi-sultanate-state-building", "apwh-u1-baghdad-merchant-ulema-network"], "connectionNotes": {"apwh-u1-delhi-sultanate-state-building": "Both developments show how Islamic institutions interacted with a predominantly Hindu South Asian society without erasing religious distinctions.", "apwh-u1-baghdad-merchant-ulema-network": "Mobile Muslim teachers and shared religious networks help compare the spread and local adaptation of Islam across regions."}, "unit": 1}, "apwh-u1-baghdad-abbasid-knowledge-hub": {"id": "apwh-u1-baghdad-abbasid-knowledge-hub", "examSkills": ["Causation", "CCOT"], "locationNumber": "3", "mainEventKey": "world-event-3-0", "title": "Baghdad as an Abbasid Knowledge Hub", "dateLabel": "762–1258", "startYear": 762, "endYear": 1258, "summary": "Abbasid Baghdad connected scholars who preserved and developed Greek, Persian, and Indian learning.", "significance": "Translation, scholarship, and urban patronage made Baghdad a major center for knowledge that circulated across the Islamic world and beyond.", "keyPeople": [{"name": "al-Khwarizmi", "role": "A Baghdad-based scholar whose mathematical work helped develop algebra and transmit numerical methods."}], "keyTerms": [{"term": "House of Wisdom", "explanation": "The name associated with Abbasid scholarly and translation activity in Baghdad."}, {"term": "ulama", "explanation": "Learned Muslim scholars who interpreted and taught Islamic religious and legal traditions."}], "evidence": ["Baghdad scholars translated and studied works drawn from Greek, Persian, and Indian traditions.", "Abbasid patronage supported advances in mathematics, medicine, astronomy, and philosophy."], "examConnection": "Use Baghdad to explain how states and cities preserved, combined, and transmitted knowledge across regional and religious boundaries.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.2"}, "topicCodes": ["1.2", "1.7"], "themeIds": ["CDI", "TEC"], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-baghdad-merchant-ulema-network"], "connectionNotes": {"apwh-u1-baghdad-merchant-ulema-network": "Scholarship, religious learning, and trusted urban networks reinforced Baghdad's wider role in the Islamic world."}, "revisionSources": ["https://www.metmuseum.org/ja/essays/the-art-of-the-abbasid-period-750-1258"], "authorship": "teacher-revised", "revisionDate": "2026-10-25", "sourceNote": "Original AMSCO locator retained as legacy metadata, not a claim of verbatim verification. Revised wording is a teacher-authored synthesis; use revisionSources and the review ledger for verification.", "unit": 1}, "apwh-u1-timbuktu-mali-gold-salt-tax": {"id": "apwh-u1-timbuktu-mali-gold-salt-tax", "examSkills": ["Causation"], "locationNumber": "73", "mainEventKey": "world-event-73-0", "title": "Mali, Gold, Salt, and Transit Taxation", "dateLabel": "1235–1450", "startYear": 1235, "endYear": 1450, "summary": "Mali taxed commerce in gold, salt, and other goods moving between West Africa and trans-Saharan markets.", "significance": "Transit revenue funded cavalry and state authority, linking Mali's political strength to control of trade routes and productive regions.", "keyPeople": [{"name": "Sundiata Keita", "role": "Founded the Mali Empire and established the dynasty that controlled important West African trade corridors."}], "keyTerms": [{"term": "transit tax", "explanation": "A levy placed on goods entering, leaving, or passing through a ruler's territory."}, {"term": "trans-Saharan trade", "explanation": "Caravan exchange connecting West Africa with North Africa across the Sahara."}], "evidence": ["Mali controlled access to important West African gold-producing regions and taxed goods moving through its territory.", "Caravans exchanged West African gold for salt, textiles, horses, and other North African goods."], "examConnection": "Use Mali to explain how African states converted control of trade routes and commodities into military and political power.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.5; Topic 2.2 trade mechanism context"}, "topicCodes": ["1.5", "1.7"], "themeIds": ["ECN", "GOV"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-timbuktu-mansa-musa-pilgrimage"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-timbuktu-mansa-musa-pilgrimage": "Revenue from Mali's control of trade helped finance Mansa Musa's pilgrimage and public display of wealth."}, "unit": 1}, "apwh-u1-timbuktu-islamic-learning-griots": {"id": "apwh-u1-timbuktu-islamic-learning-griots", "examSkills": ["Comparison", "CCOT"], "locationNumber": "73", "mainEventKey": "world-event-73-2", "title": "Islamic Learning and Griot Memory", "dateLabel": "1300–1450", "startYear": 1300, "endYear": 1450, "summary": "Timbuktu combined Islamic schools and manuscript learning with West African traditions of oral historical memory.", "significance": "Written scholarship and griot performance coexisted, showing that expanding Islam added institutions without erasing local ways of preserving history.", "keyPeople": [{"name": "griots", "role": "Specialists who preserved genealogies, political memory, and community histories through oral performance."}], "keyTerms": [{"term": "madrasa", "explanation": "An institution for advanced study in Islamic subjects and related fields of learning."}, {"term": "griot", "explanation": "A West African oral historian and performer who preserves genealogies and accounts of rulers."}], "evidence": ["Timbuktu developed a reputation for Islamic scholarship, schools, and manuscript culture.", "Griots continued to preserve dynastic and community memory through recitation and music."], "examConnection": "Use Timbuktu to explain cultural continuity and change: Islamic learning expanded while oral specialists retained important social roles.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.5"}, "topicCodes": ["1.5", "1.7"], "themeIds": ["CDI", "SIO"], "causeStudyPointIds": ["apwh-u1-timbuktu-mansa-musa-pilgrimage"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-baghdad-merchant-ulema-network"], "connectionNotes": {"apwh-u1-timbuktu-mansa-musa-pilgrimage": "Mansa Musa's post-pilgrimage patronage strengthened mosques, schools, and scholarly connections in Mali.", "apwh-u1-baghdad-merchant-ulema-network": "Commercial and scholarly networks carried Islamic institutions while local societies retained distinct cultural practices."}, "unit": 1}, "apwh-u1-timbuktu-mansa-musa-pilgrimage": {"id": "apwh-u1-timbuktu-mansa-musa-pilgrimage", "examSkills": ["Causation", "Contextualization"], "locationNumber": "73", "mainEventKey": "world-event-73-3", "title": "Mansa Musa's Pilgrimage", "dateLabel": "1324", "startYear": 1324, "endYear": 1324, "summary": "Mansa Musa traveled to Mecca, displayed Mali's wealth, and returned with stronger ties to Islamic learning.", "significance": "The pilgrimage advertised Mali's resources abroad and helped its ruler use Islamic patronage to reinforce authority and scholarly life at home.", "keyPeople": [{"name": "Mansa Musa", "role": "Mali ruler whose pilgrimage connected his empire more visibly to North Africa and the wider Islamic world."}], "keyTerms": [{"term": "hajj", "explanation": "The pilgrimage to Mecca required of Muslims who are able to undertake it."}, {"term": "patronage", "explanation": "Political and financial support given to religious institutions, scholars, artists, or builders."}], "evidence": ["Mansa Musa distributed enough gold during his journey to make Mali's wealth famous in the Mediterranean world.", "After the pilgrimage, he sponsored mosques, religious schools, and scholars in Mali."], "examConnection": "Use the pilgrimage to explain how an African ruler employed religion and wealth to build legitimacy and strengthen interregional connections.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.5"}, "topicCodes": ["1.5", "1.7"], "themeIds": ["GOV", "ECN", "CDI"], "causeStudyPointIds": ["apwh-u1-timbuktu-mali-gold-salt-tax"], "effectStudyPointIds": ["apwh-u1-timbuktu-islamic-learning-griots"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-timbuktu-mali-gold-salt-tax": "Revenue from Mali's control of trade helped finance Mansa Musa's pilgrimage and public display of wealth.", "apwh-u1-timbuktu-islamic-learning-griots": "Mansa Musa's post-pilgrimage patronage strengthened mosques, schools, and scholarly connections in Mali."}, "unit": 1}, "apwh-u1-tenochtitlan-chinampas-urban-state": {"id": "apwh-u1-tenochtitlan-chinampas-urban-state", "examSkills": ["Causation", "Comparison"], "locationNumber": "49", "mainEventKey": "world-event-49-0", "title": "Chinampas and Urban State Capacity", "dateLabel": "1325–1450", "startYear": 1325, "endYear": 1450, "summary": "Mexica farmers expanded chinampa agriculture around Tenochtitlan to support a dense island capital and its growing political power.", "significance": "Intensive lake agriculture generated reliable food surpluses that sustained urban specialists, armies, rulers, and the institutions of an expanding state.", "keyPeople": [{"name": "Mexica farmers", "role": "Built and maintained raised agricultural plots that supplied maize, vegetables, and flowers to the capital."}], "keyTerms": [{"term": "chinampa", "explanation": "A raised, highly productive agricultural plot constructed in the shallow waters of the Valley of Mexico."}, {"term": "Tenochtitlan", "explanation": "The Mexica island capital that became the center of the Aztec Empire."}], "evidence": ["Chinampas used fertile lake mud and carefully managed waterways to produce repeated harvests close to Tenochtitlan.", "Agricultural surplus helped feed a large urban population that included artisans, merchants, priests, soldiers, and officials."], "examConnection": "Use chinampas to explain how societies adapted environments and converted agricultural productivity into urban growth and state capacity.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["ENV", "ECN", "GOV"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-tenochtitlan-triple-alliance-tribute"], "relatedStudyPointIds": ["apwh-u1-cusco-ayllu-mita-labor"], "connectionNotes": {"apwh-u1-tenochtitlan-triple-alliance-tribute": "Intensive chinampa agriculture helped sustain the large urban population and military resources from which Mexica rulers expanded tribute demands.", "apwh-u1-cusco-ayllu-mita-labor": "Both states adapted difficult environments through organized labor, although chinampas intensified lake agriculture while Inca communities managed highland production and terraces."}, "unit": 1}, "apwh-u1-tenochtitlan-religion-warfare-legitimacy": {"id": "apwh-u1-tenochtitlan-religion-warfare-legitimacy", "examSkills": ["Comparison", "Contextualization"], "locationNumber": "49", "mainEventKey": "world-event-49-0", "title": "Religion, Warfare, and Mexica Legitimacy", "dateLabel": "1325–1450", "startYear": 1325, "endYear": 1450, "summary": "Mexica rulers linked warfare, tribute, and public religious ritual to a sacred story of their capital and empire.", "significance": "Religious ceremonies presented conquest and sacrifice as obligations within a cosmic order, helping rulers justify expansion and mobilize society.", "keyPeople": [{"name": "Mexica priests", "role": "Conducted state rituals that connected military success and royal authority to the gods."}], "keyTerms": [{"term": "Huitzilopochtli", "explanation": "The Mexica patron deity associated with the sun, warfare, and the sacred identity of Tenochtitlan."}, {"term": "human sacrifice", "explanation": "A state ritual that Mexica leaders connected to sustaining cosmic order and displaying political power."}], "evidence": ["The Templo Mayor placed state ceremony at the physical and symbolic center of Tenochtitlan.", "Military campaigns supplied captives for ritual and demonstrated the ruler’s ability to defend and expand the sacred community."], "examConnection": "Use Mexica ritual and warfare to compare how rulers in different regions used belief systems and public display to legitimate political authority.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["CDI", "GOV"], "causeStudyPointIds": ["apwh-u1-tenochtitlan-triple-alliance-tribute"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-tenochtitlan-triple-alliance-tribute": "Tribute warfare supplied wealth and captives while public ritual presented Mexica expansion as part of a sacred political order."}, "unit": 1}, "apwh-u1-tenochtitlan-triple-alliance-tribute": {"id": "apwh-u1-tenochtitlan-triple-alliance-tribute", "examSkills": ["Causation", "Comparison"], "locationNumber": "49", "mainEventKey": "world-event-49-0", "title": "Triple Alliance and Tribute Empire", "dateLabel": "1428–1450", "startYear": 1428, "endYear": 1450, "summary": "Tenochtitlan joined Texcoco and Tlacopan in the Triple Alliance and used conquest to collect tribute from subject communities.", "significance": "Tribute moved food, textiles, labor, and luxury goods toward the imperial center, strengthening rulers while creating resentment among subject peoples.", "keyPeople": [{"name": "Itzcoatl", "role": "Led Tenochtitlan during the formation of the Triple Alliance and the early expansion of its tribute power."}], "keyTerms": [{"term": "Triple Alliance", "explanation": "The political and military alliance of Tenochtitlan, Texcoco, and Tlacopan formed in 1428."}, {"term": "tribute empire", "explanation": "An empire that leaves many conquered communities locally governed while requiring regular payments and obedience."}], "evidence": ["Conquered communities delivered specified goods such as maize, cloth, cacao, feathers, and military equipment.", "The alliance concentrated an increasing share of tribute and influence in Tenochtitlan."], "examConnection": "Use the Triple Alliance to compare tribute-based imperial rule with other systems that extracted taxes, goods, or labor from subject populations.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["GOV", "ECN"], "causeStudyPointIds": ["apwh-u1-tenochtitlan-chinampas-urban-state"], "effectStudyPointIds": ["apwh-u1-tenochtitlan-religion-warfare-legitimacy"], "relatedStudyPointIds": ["apwh-u1-cusco-ayllu-mita-labor"], "connectionNotes": {"apwh-u1-tenochtitlan-chinampas-urban-state": "Intensive chinampa agriculture helped sustain the large urban population and military resources from which Mexica rulers expanded tribute demands.", "apwh-u1-tenochtitlan-religion-warfare-legitimacy": "Tribute warfare supplied wealth and captives while public ritual presented Mexica expansion as part of a sacred political order.", "apwh-u1-cusco-ayllu-mita-labor": "The Aztec tribute system and the Inca mit'a system extracted resources differently: one emphasized subject payments, while the other mobilized labor through communities."}, "unit": 1}, "apwh-u1-cusco-pachacuti-tawantinsuyu": {"id": "apwh-u1-cusco-pachacuti-tawantinsuyu", "examSkills": ["Causation", "Contextualization"], "locationNumber": "50", "mainEventKey": "world-event-50-0", "title": "Pachacuti and Tawantinsuyu", "dateLabel": "1438–1450", "startYear": 1438, "endYear": 1450, "summary": "Pachacuti transformed the kingdom centered on Cusco into the expanding Inca state called Tawantinsuyu.", "significance": "Expansion joined contrasting highland and coastal environments under a ruler who reorganized territory, labor, and political relationships from Cusco.", "keyPeople": [{"name": "Pachacuti", "role": "Inca ruler credited with reorganizing Cusco and beginning the rapid imperial expansion of Tawantinsuyu."}], "keyTerms": [{"term": "Tawantinsuyu", "explanation": "The Inca name for their empire, often translated as the Land of the Four Quarters."}, {"term": "vertical economy", "explanation": "Andean access to products from different elevations through communities, colonies, and exchange."}], "evidence": ["Pachacuti organized conquered territory into four broad regions connected to the capital at Cusco.", "Inca expansion linked ecological zones that produced different crops, animals, and raw materials."], "examConnection": "Use Pachacuti to explain how military expansion and environmental diversity shaped the administrative needs of the Inca state.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["GOV", "ENV"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-cusco-ayllu-mita-labor"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-cusco-ayllu-mita-labor": "Rapid territorial expansion required Inca rulers to organize local ayllus and rotate labor obligations across a much larger state."}, "unit": 1}, "apwh-u1-cusco-roads-quipu-administration": {"id": "apwh-u1-cusco-roads-quipu-administration", "examSkills": ["Causation", "Comparison"], "locationNumber": "50", "mainEventKey": "world-event-50-0", "title": "Roads, Quipu, and Imperial Administration", "dateLabel": "1438–1450", "startYear": 1438, "endYear": 1450, "summary": "Inca roads, runners, storehouses, and quipu records connected distant Andean communities to administrators centered on Cusco.", "significance": "Transport and recordkeeping allowed officials to mobilize workers, count resources, move armies, and redistribute supplies without alphabetic writing.", "keyPeople": [{"name": "quipucamayocs", "role": "Specialists who made and interpreted knotted-cord records for administrators."}], "keyTerms": [{"term": "quipu", "explanation": "A system of knotted cords used to record numerical and administrative information."}, {"term": "chasqui", "explanation": "A relay runner who carried messages and goods along the Inca road system."}], "evidence": ["A wide road network connected provincial centers, state storehouses, and military routes through difficult terrain.", "Quipu records helped officials track population, tribute obligations, labor, and stored resources."], "examConnection": "Use roads and quipu to compare how large states solved the shared problems of communication, recordkeeping, and resource mobilization.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.4"}, "topicCodes": ["1.4", "1.7"], "themeIds": ["GOV", "TEC"], "causeStudyPointIds": ["apwh-u1-cusco-ayllu-mita-labor"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-cusco-ayllu-mita-labor": "Mobilized mit'a labor built and maintained roads, while officials used quipu records to track resources and obligations."}, "unit": 1}, "apwh-u1-london-manorial-feudal-order": {"id": "apwh-u1-london-manorial-feudal-order", "examSkills": ["CCOT", "Contextualization"], "locationNumber": "23", "mainEventKey": "world-event-23-0", "title": "Manorial Agriculture and Feudal Order", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "London serves as a regional anchor for a Europe in which manors organized rural production and feudal ties distributed political and military obligations.", "significance": "These overlapping local institutions shaped political fragmentation and agricultural life even as monarchies, towns, and commerce gradually expanded.", "keyPeople": [{"name": "manorial lords and peasants", "role": "Negotiated rents, labor services, protection, and access to land within local agricultural communities."}], "keyTerms": [{"term": "manorialism", "explanation": "A rural economic and social system organized around an estate, its lord, and dependent peasant labor."}, {"term": "feudalism", "explanation": "A broad label for decentralized political relationships based on landholding, loyalty, and military obligation."}], "evidence": ["Most Europeans lived in agricultural communities where peasants owed rents or labor to landholding elites.", "Kings often depended on nobles whose local land, castles, and armed followers limited centralized authority."], "examConnection": "Use manorial and feudal relationships to contextualize Europe’s decentralized order and trace continuity alongside the later growth of towns and monarchies.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.6"}, "topicCodes": ["1.6", "1.7"], "themeIds": ["SIO", "ECN"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u1-london-towns-guilds-commerce"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-london-towns-guilds-commerce": "Agricultural production and population recovery supported markets and towns whose merchants and guilds operated beyond individual manors."}, "unit": 1}, "apwh-u1-london-towns-guilds-commerce": {"id": "apwh-u1-london-towns-guilds-commerce", "examSkills": ["Causation", "CCOT"], "locationNumber": "23", "mainEventKey": "world-event-23-0", "title": "Towns, Guilds, and Commercial Growth", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "London serves as a representative map anchor for the broader European growth of towns and merchant and craft guilds that regulated economic life.", "significance": "Urban and commercial growth created institutions and social groups with interests extending beyond manorial agriculture and local noble authority.", "keyPeople": [{"name": "guild members", "role": "Merchants and artisans who regulated occupations, trained apprentices, and defended collective privileges."}], "keyTerms": [{"term": "guild", "explanation": "An association of merchants or craftspeople that regulated standards, training, prices, and market access."}, {"term": "commercial growth", "explanation": "The expansion of markets, specialized production, money exchange, and long-distance trade."}], "evidence": ["Merchant guilds protected trade privileges, while craft guilds supervised apprenticeship and product standards.", "London connected regional agricultural production with wider North Sea and European commercial networks."], "examConnection": "Use guilds and towns to explain how expanding commerce changed European social organization while many rural manorial practices continued.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.6"}, "topicCodes": ["1.6", "1.7"], "themeIds": ["ECN", "SIO"], "causeStudyPointIds": ["apwh-u1-london-manorial-feudal-order"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u1-london-manorial-feudal-order": "Agricultural production and population recovery supported markets and towns whose merchants and guilds operated beyond individual manors."}, "unit": 1}, "apwh-u1-london-magna-carta-monarchy": {"id": "apwh-u1-london-magna-carta-monarchy", "examSkills": ["Comparison", "Contextualization"], "locationNumber": "23", "mainEventKey": "world-event-23-0", "title": "Magna Carta and Negotiated Monarchy", "dateLabel": "1215", "startYear": 1215, "endYear": 1215, "summary": "London and England serve as a representative map anchor for a European case of negotiated monarchy: English barons compelled King John to seal Magna Carta at Runnymede during political conflict.", "significance": "The charter expressed medieval elite bargaining and the principle that a monarch faced established legal constraints, not a system of modern democracy.", "keyPeople": [{"name": "King John", "role": "Accepted Magna Carta after conflict with English barons over failed wars, taxation, and arbitrary royal actions."}], "keyTerms": [{"term": "Magna Carta", "explanation": "A 1215 charter protecting specific baronial and ecclesiastical privileges and limiting some royal actions."}, {"term": "negotiated monarchy", "explanation": "Rule shaped by bargaining between a monarch and powerful groups whose cooperation the ruler needed."}], "evidence": ["The charter arose from a baronial revolt and chiefly protected the interests of nobles, the church, and other privileged groups.", "Clauses required the king to observe inherited customs and forms of lawful judgment in specified disputes."], "examConnection": "Use Magna Carta to compare constraints on rulers while avoiding anachronism: it limited some royal behavior but did not create modern democracy.", "source": {"id": "amsco-apwh-u1", "locator": "AMSCO AP World History, Unit 1, Topic 1.6"}, "topicCodes": ["1.6", "1.7"], "themeIds": ["GOV"], "causeStudyPointIds": [], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u1-delhi-sultanate-state-building"], "connectionNotes": {"apwh-u1-delhi-sultanate-state-building": "Both cases reveal negotiations between rulers and powerful groups, but Magna Carta formalized baronial constraints while Delhi sultans balanced minority rule with military and local political accommodation."}, "unit": 1}, "apwh-u2-karakorum-mongol-unification-conquest": {"id": "apwh-u2-karakorum-mongol-unification-conquest", "locationNumber": "8", "mainEventKey": "world-event-8-0", "title": "Mongol Unification and Conquest", "dateLabel": "1206–1227", "startYear": 1206, "endYear": 1227, "summary": "Temujin unified Mongol groups and used disciplined cavalry, mobility, and terror to build a conquest state across Eurasia.", "significance": "Conquest brought previously divided land routes under related Mongol authorities and created the political conditions for faster trade and communication.", "keyPeople": [{"name": "Genghis Khan", "role": "Unified Mongol groups in 1206 and directed conquests that connected territories from northern China toward Central and Southwest Asia."}], "keyTerms": [{"term": "kurultai", "explanation": "An assembly of Mongol leaders that selected a khan and affirmed major political decisions."}, {"term": "decimal organization", "explanation": "A military structure grouping warriors into units of tens, hundreds, thousands, and ten-thousands."}], "evidence": ["A 1206 kurultai recognized Temujin as Genghis Khan after he defeated rival Mongol groups.", "Mongol forces conquered the Khwarazmian realm and linked Central Asian routes to a rapidly expanding empire."], "examConnection": "Use Mongol unification as a political cause of expanded exchange, then explain the protection mechanism instead of treating conquest and trade as a simple sequence.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.2 and 2.7"}, "sequence": 1, "topicCodes": ["2.2", "2.7"], "themeIds": ["GOV"], "examSkills": ["Causation", "CCOT"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-karakorum-pax-mongolica-protected-trade"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-karakorum-pax-mongolica-protected-trade": "Mongol conquest brought previously divided routes under related authorities that could protect merchants and punish raiders."}, "unit": 2}, "apwh-u2-karakorum-pax-mongolica-protected-trade": {"id": "apwh-u2-karakorum-pax-mongolica-protected-trade", "locationNumber": "8", "mainEventKey": "world-event-8-0", "title": "Pax Mongolica and Protected Trade", "dateLabel": "c. 1250–c. 1350", "startYear": 1250, "endYear": 1350, "summary": "Mongol authorities repaired routes, punished raiders, and protected merchants across a large portion of Eurasia.", "significance": "Lower protection costs allowed more merchants, envoys, and travelers to use overland routes and helped create a new high point in Silk Roads exchange.", "keyPeople": [{"name": "Mongol khans", "role": "Governed related khanates that protected routes, enforced laws, and supported movement across imperial boundaries."}], "keyTerms": [{"term": "Pax Mongolica", "explanation": "The period of relative security and connectivity across Mongol-ruled Eurasia."}, {"term": "protection cost", "explanation": "The risk and expense merchants face from robbery, war, tolls, and uncertain enforcement."}], "evidence": ["Mongol rulers repaired roads and used soldiers to protect commercial routes from raiders.", "Merchants could cross territories governed by related Mongol states with more predictable rules and lower risk."], "examConnection": "Use the Pax Mongolica to explain how political control caused trade growth by reducing risk, not merely by placing more territory under one empire.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.1, 2.2, and 2.7"}, "sequence": 2, "topicCodes": ["2.1", "2.2", "2.7"], "themeIds": ["GOV", "ECN"], "examSkills": ["Causation"], "causeStudyPointIds": ["apwh-u2-karakorum-mongol-unification-conquest"], "effectStudyPointIds": ["apwh-u2-karakorum-yam-relay-cross-cultural-transfer", "apwh-u2-cairo-black-death-demographic-change"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-karakorum-mongol-unification-conquest": "Mongol conquest brought previously divided routes under related authorities that could protect merchants and punish raiders.", "apwh-u2-karakorum-yam-relay-cross-cultural-transfer": "Protected routes and relay stations accelerated the movement of envoys, specialists, information, and technologies across Eurasia.", "apwh-u2-cairo-black-death-demographic-change": "Denser and safer Eurasian movement also allowed plague-bearing hosts and vectors to travel farther through connected routes."}, "unit": 2}, "apwh-u2-karakorum-yam-relay-cross-cultural-transfer": {"id": "apwh-u2-karakorum-yam-relay-cross-cultural-transfer", "locationNumber": "8", "mainEventKey": "world-event-8-0", "title": "The Yam Relay and Cross-Cultural Transfer", "dateLabel": "c. 1250–1368", "startYear": 1250, "endYear": 1368, "summary": "Relay stations and protected movement carried official messages, specialists, technologies, and knowledge across Mongol Eurasia.", "significance": "The same infrastructure used for imperial control accelerated cultural and technological transfer among China, Central Asia, the Islamic world, and Europe.", "keyPeople": [{"name": "Mongol relay riders", "role": "Moved messages and official travelers between staffed stations across long imperial distances."}], "keyTerms": [{"term": "yam", "explanation": "The Mongol imperial relay network of stations, fresh horses, supplies, and authorized travelers."}, {"term": "technology transfer", "explanation": "The movement and adaptation of technical knowledge between societies."}], "evidence": ["Relay stations provided fresh horses and supplies so official messages could move rapidly across the empire.", "Paper, gunpowder knowledge, medical learning, and skilled workers traveled through intensified Eurasian contacts."], "examConnection": "Use the yam to show that empire affected more than commerce: administrative infrastructure also changed the speed of cultural and technological exchange.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.2 and 2.5"}, "sequence": 3, "topicCodes": ["2.2", "2.5"], "themeIds": ["TEC", "CDI"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": ["apwh-u2-karakorum-pax-mongolica-protected-trade"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-samarkand-timurid-commercial-learning-hub"], "connectionNotes": {"apwh-u2-karakorum-pax-mongolica-protected-trade": "Protected routes and relay stations accelerated the movement of envoys, specialists, information, and technologies across Eurasia.", "apwh-u2-samarkand-timurid-commercial-learning-hub": "Both cases show that commercial routes also moved specialists and knowledge, although one was an imperial relay and the other an urban center."}, "unit": 2}, "apwh-u2-samarkand-caravanserai-merchant-infrastructure": {"id": "apwh-u2-samarkand-caravanserai-merchant-infrastructure", "locationNumber": "9", "mainEventKey": "world-event-9-0", "title": "Caravanserai and Merchant Infrastructure", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "Caravanserai gave merchants recurring places to rest animals, store goods, obtain information, and conduct exchange along overland routes.", "significance": "A chain of predictable service nodes reduced the logistical cost of long journeys and made cities such as Samarkand more useful to interregional merchants.", "keyPeople": [{"name": "caravan merchants", "role": "Organized animals, guards, credit, and goods for long-distance movement between commercial cities."}], "keyTerms": [{"term": "caravanserai", "explanation": "A fortified roadside lodging and commercial station serving merchants and pack animals."}, {"term": "caravan", "explanation": "A group of travelers and pack animals moving together for security and logistical support."}], "evidence": ["Caravanserai supplied lodging, water, storage, and market space at recurring points along major routes.", "Improved camel saddles allowed pack animals to carry heavier loads across arid terrain."], "examConnection": "Use caravanserai as evidence that infrastructure caused network growth by lowering recurring transport and information costs for merchants.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.1 and 2.7"}, "sequence": 1, "topicCodes": ["2.1", "2.7"], "themeIds": ["ECN", "TEC"], "examSkills": ["Causation"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-samarkand-timurid-commercial-learning-hub"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-samarkand-timurid-commercial-learning-hub": "Reliable lodging, storage, and market infrastructure helped Samarkand attract merchants and scholars from multiple regions."}, "unit": 2}, "apwh-u2-samarkand-bills-exchange-banking-houses": {"id": "apwh-u2-samarkand-bills-exchange-banking-houses", "locationNumber": "9", "mainEventKey": "world-event-9-0", "title": "Bills of Exchange and Banking Houses", "dateLabel": "1300–1450", "startYear": 1300, "endYear": 1450, "summary": "Credit instruments allowed merchants to transfer value without carrying the full payment in heavy coin across dangerous routes.", "significance": "Bills of exchange and banking houses reduced theft risk and connected commercial practices developed in Asia with expanding financial institutions farther west.", "keyPeople": [{"name": "merchant-bankers", "role": "Accepted deposits, verified written claims, extended credit, and converted commercial promises into payment."}], "keyTerms": [{"term": "bill of exchange", "explanation": "A written order or promise to pay a specified person a specified amount at an agreed time."}, {"term": "banking house", "explanation": "A commercial institution that accepted deposits, exchanged currencies, and provided credit or payment services."}], "evidence": ["Merchants could deposit value in one place and use written instruments to obtain payment elsewhere.", "Banking houses expanded in European commercial cities during the 1300s as long-distance trade increased."], "examConnection": "Compare bills of exchange with maritime technology: both expanded trade, but one reduced payment risk while the other reduced transport uncertainty.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.1 and 2.7"}, "sequence": 2, "topicCodes": ["2.1", "2.7"], "themeIds": ["ECN"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-samarkand-timurid-commercial-learning-hub"], "relatedStudyPointIds": ["apwh-u2-malacca-monsoon-navigation-maritime-technology"], "connectionNotes": {"apwh-u2-samarkand-timurid-commercial-learning-hub": "Credit instruments reduced the need to carry coin and supported the commercial traffic that sustained a cosmopolitan center.", "apwh-u2-malacca-monsoon-navigation-maritime-technology": "Maritime technology reduced transport uncertainty while financial instruments reduced payment risk; both lowered the cost of exchange."}, "unit": 2}, "apwh-u2-samarkand-timurid-commercial-learning-hub": {"id": "apwh-u2-samarkand-timurid-commercial-learning-hub", "locationNumber": "9", "mainEventKey": "world-event-9-0", "title": "Timurid Samarkand as a Commercial and Learning Hub", "dateLabel": "1370–1450", "startYear": 1370, "endYear": 1450, "summary": "Timurid patronage made Samarkand a center where merchants, artisans, architects, and scholars from several regions met.", "significance": "The city demonstrates continuity between commercial connectivity and knowledge exchange even as conquest changed the rulers controlling Central Asian routes.", "keyPeople": [{"name": "Ulugh Beg", "role": "A Timurid ruler and patron of astronomy and education who sponsored a major madrasa in Samarkand."}], "keyTerms": [{"term": "Timurid Empire", "explanation": "The Central Asian state founded by Timur that controlled important overland routes and cities."}, {"term": "madrasa", "explanation": "An institution of advanced Islamic learning that could also support mathematics, astronomy, and law."}], "evidence": ["Timur made Samarkand his capital and drew skilled workers and cultural resources toward the city.", "The Ulugh Beg Madrasa, built in the early 1400s, linked political patronage with scholarly activity."], "examConnection": "Use Samarkand to explain continuity and change: conquest disrupted regions, yet rulers continued using trade cities to collect wealth and patronize learning.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.1 and 2.5"}, "sequence": 3, "topicCodes": ["2.1", "2.5"], "themeIds": ["CDI", "TEC"], "examSkills": ["CCOT", "Comparison"], "causeStudyPointIds": ["apwh-u2-samarkand-caravanserai-merchant-infrastructure", "apwh-u2-samarkand-bills-exchange-banking-houses"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-karakorum-yam-relay-cross-cultural-transfer"], "connectionNotes": {"apwh-u2-samarkand-caravanserai-merchant-infrastructure": "Reliable lodging, storage, and market infrastructure helped Samarkand attract merchants and scholars from multiple regions.", "apwh-u2-samarkand-bills-exchange-banking-houses": "Credit instruments reduced the need to carry coin and supported the commercial traffic that sustained a cosmopolitan center.", "apwh-u2-karakorum-yam-relay-cross-cultural-transfer": "Both cases show that commercial routes also moved specialists and knowledge, although one was an imperial relay and the other an urban center."}, "unit": 2}, "apwh-u2-malacca-monsoon-navigation-maritime-technology": {"id": "apwh-u2-malacca-monsoon-navigation-maritime-technology", "locationNumber": "2", "mainEventKey": "world-event-2-1", "title": "Monsoon Navigation and Maritime Technology", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "Knowledge of monsoon winds and improved sails, rudders, compasses, and astrolabes made Indian Ocean travel more predictable.", "significance": "Predictable seasons and better navigation allowed merchants to plan recurring voyages, carry heavier cargo, and connect distant ports at lower cost.", "keyPeople": [{"name": "Indian Ocean sailors", "role": "Combined seasonal wind knowledge with navigational instruments and ship designs suited to long-distance trade."}], "keyTerms": [{"term": "monsoon winds", "explanation": "Seasonally reversing wind patterns that structured sailing schedules across the Indian Ocean."}, {"term": "lateen sail", "explanation": "A triangular sail that helped ships maneuver across changing wind directions."}], "evidence": ["Sailors timed voyages around winds that blew from the northeast in one season and the southwest in another.", "Compasses, astrolabes, sternpost rudders, and compartmentalized ships improved direction, control, and cargo security."], "examConnection": "Use monsoon knowledge and ship technology as causal evidence for Indian Ocean growth, then distinguish predictable timing from political protection.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 1, "topicCodes": ["2.3", "2.7"], "themeIds": ["TEC", "ECN"], "examSkills": ["Causation"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-malacca-strategic-port-state"], "relatedStudyPointIds": ["apwh-u2-samarkand-bills-exchange-banking-houses"], "connectionNotes": {"apwh-u2-malacca-strategic-port-state": "Predictable monsoon sailing and improved ships concentrated recurring traffic at the Strait of Malacca.", "apwh-u2-samarkand-bills-exchange-banking-houses": "Maritime technology reduced transport uncertainty while financial instruments reduced payment risk; both lowered the cost of exchange."}, "unit": 2}, "apwh-u2-malacca-strategic-port-state": {"id": "apwh-u2-malacca-strategic-port-state", "locationNumber": "2", "mainEventKey": "world-event-2-1", "title": "Malacca as a Strategic Port State", "dateLabel": "c. 1400–1450", "startYear": 1400, "endYear": 1450, "summary": "Malacca used its position on a narrow maritime passage to tax ships, protect traffic, and become a major commercial entrepot.", "significance": "The port converted predictable trade flows into public revenue and naval power, showing how states could grow from exchange rather than agricultural production.", "keyPeople": [{"name": "Malaccan sultans", "role": "Collected port revenue, protected the strait, and governed a commercial state serving merchants from many regions."}], "keyTerms": [{"term": "entrepot", "explanation": "A port where merchants unload, store, exchange, and re-export goods from multiple regions."}, {"term": "Strait of Malacca", "explanation": "The narrow passage linking the Indian Ocean with the South China Sea and East Asian markets."}], "evidence": ["Malacca charged ships using the strait and used revenue to support protection against piracy.", "Its prosperity depended primarily on trade and services rather than farming, mining, or large-scale manufacturing."], "examConnection": "Compare Malacca with Kilwa to explain how strategic ports converted maritime traffic into political authority through different local institutions.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 2, "topicCodes": ["2.3", "2.7"], "themeIds": ["ECN", "GOV"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": ["apwh-u2-malacca-monsoon-navigation-maritime-technology"], "effectStudyPointIds": ["apwh-u2-malacca-merchant-diasporas-spread-islam"], "relatedStudyPointIds": ["apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce"], "connectionNotes": {"apwh-u2-malacca-monsoon-navigation-maritime-technology": "Predictable monsoon sailing and improved ships concentrated recurring traffic at the Strait of Malacca.", "apwh-u2-malacca-merchant-diasporas-spread-islam": "A protected and heavily visited port encouraged foreign merchants to reside, marry, and establish religious communities.", "apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce": "Kilwa and Malacca both converted strategic access to maritime exchange into urban wealth and political power."}, "unit": 2}, "apwh-u2-kilwa-gold-ivory-regional-specialization": {"id": "apwh-u2-kilwa-gold-ivory-regional-specialization", "locationNumber": "85", "mainEventKey": "world-event-85-0", "title": "Gold, Ivory, and Regional Specialization", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "Kilwa linked inland supplies of gold and ivory to overseas demand and exchanged them for manufactured and luxury goods.", "significance": "Long-distance demand encouraged regions to specialize in goods they could supply competitively and tied coastal prosperity to inland production and transport.", "keyPeople": [{"name": "East African traders", "role": "Moved inland commodities toward coastal markets and distributed imported goods back through regional networks."}], "keyTerms": [{"term": "regional specialization", "explanation": "The concentration of production in goods a region can supply effectively for exchange."}, {"term": "hinterland", "explanation": "The inland zone connected economically to a port through production, transport, and markets."}], "evidence": ["Gold from the Great Zimbabwe region moved through ports such as Sofala and into the wider coastal trade served by Kilwa.", "Ivory and other African exports were exchanged for textiles, ceramics, metal goods, and luxury products."], "examConnection": "Use Kilwa to explain how expanding networks changed production by rewarding regional specialization and linking inland economies to maritime demand.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 2, "topicCodes": ["2.3", "2.7"], "themeIds": ["ECN"], "examSkills": ["Causation"], "causeStudyPointIds": ["apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce": "Demand from Indian Ocean merchants rewarded coastal access to inland gold, ivory, and other specialized exports."}, "unit": 2}, "apwh-u2-kilwa-swahili-cultural-synthesis": {"id": "apwh-u2-kilwa-swahili-cultural-synthesis", "locationNumber": "85", "mainEventKey": "world-event-85-0", "title": "Swahili Cultural Synthesis", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "Coastal East Africans combined Bantu linguistic and social foundations with Islamic belief and vocabulary associated with overseas contact.", "significance": "Swahili culture shows that network expansion produced locally distinct synthesis rather than replacing African identities with a uniform imported culture.", "keyPeople": [{"name": "Swahili coastal communities", "role": "Adapted Islamic institutions and overseas influences within Bantu-speaking urban societies."}], "keyTerms": [{"term": "Swahili", "explanation": "A Bantu language and coastal culture shaped partly by long contact with Arabic-speaking and Muslim merchants."}, {"term": "cultural synthesis", "explanation": "A new cultural pattern formed by combining selected elements from interacting traditions."}], "evidence": ["Swahili vocabulary incorporated Arabic terms while retaining Bantu grammatical foundations.", "Coastal elites built mosques and participated in Islam while local languages, kinship, and regional practices continued."], "examConnection": "Compare Swahili synthesis with Islam in Malacca to explain shared merchant influence and different local cultural outcomes.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.5"}, "sequence": 3, "topicCodes": ["2.3", "2.5"], "themeIds": ["CDI", "SIO"], "examSkills": ["Comparison", "CCOT"], "causeStudyPointIds": ["apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-malacca-merchant-diasporas-spread-islam"], "connectionNotes": {"apwh-u2-kilwa-swahili-city-states-indian-ocean-commerce": "Long-term commercial contact joined Bantu-speaking coastal societies with Islamic and Arabic cultural influences.", "apwh-u2-malacca-merchant-diasporas-spread-islam": "Resident Muslim merchants contributed to locally distinct forms of Islamic cultural change in Southeast Asia and the Swahili Coast."}, "unit": 2}, "apwh-u2-cairo-trans-saharan-gold-camel-caravans": {"id": "apwh-u2-cairo-trans-saharan-gold-camel-caravans", "locationNumber": "84", "mainEventKey": "world-event-84-0", "title": "Trans-Saharan Gold and Camel-Caravan Trade", "dateLabel": "1200–1450", "startYear": 1200, "endYear": 1450, "summary": "Camel caravans connected West African gold producers and states with North African markets, including the commercial world represented by Cairo.", "significance": "Transport technology and organized caravans made desert exchange profitable and linked Mali to wider Islamic and Mediterranean demand without making Cairo the route origin.", "keyPeople": [{"name": "Berber and Muslim caravan merchants", "role": "Organized camel transport, commercial trust, and exchange between West Africa and North African markets."}], "keyTerms": [{"term": "camel saddle", "explanation": "Equipment adapted to pack or riding camels that increased useful loads and control in desert travel."}, {"term": "trans-Saharan trade", "explanation": "Caravan exchange connecting West Africa with North Africa across the Sahara."}], "evidence": ["Caravans moved West African gold northward and carried salt, textiles, horses, and other goods southward.", "Camel transport and coordinated stopping points allowed merchants to cross long arid distances with bulk goods."], "examConnection": "Compare trans-Saharan caravans with Indian Ocean shipping by explaining how different environments required different transport solutions for network growth.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.4 and 2.7"}, "sequence": 1, "topicCodes": ["2.4", "2.7"], "themeIds": ["ECN", "TEC"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-cairo-mansa-musa-gold-shock"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-cairo-mansa-musa-gold-shock": "Trans-Saharan commerce made Mali's gold wealth visible in Cairo and supplied the resources displayed during Mansa Musa's pilgrimage."}, "unit": 2}, "apwh-u2-cairo-mansa-musa-gold-shock": {"id": "apwh-u2-cairo-mansa-musa-gold-shock", "locationNumber": "84", "mainEventKey": "world-event-84-0", "title": "Mansa Musa's Gold Shock", "dateLabel": "1324", "startYear": 1324, "endYear": 1324, "summary": "Mansa Musa distributed large quantities of gold in Cairo during his hajj, making Mali's wealth visible far beyond West Africa.", "significance": "The episode demonstrates how a trans-Saharan network carried wealth, reputation, religious affiliation, and economic effects between distant regions.", "keyPeople": [{"name": "Mansa Musa", "role": "The Mali ruler whose 1324 pilgrimage displayed gold wealth and strengthened connections with the wider Islamic world."}], "keyTerms": [{"term": "hajj", "explanation": "The pilgrimage to Mecca required of Muslims who are able to undertake it."}, {"term": "gold shock", "explanation": "A sudden increase in available gold that lowers its local value relative to goods and other money."}], "evidence": ["Mansa Musa traveled through Cairo with a large entourage and distributed gold during the journey.", "Contemporary and later accounts associated his spending with a prolonged decline in the local value of gold."], "examConnection": "Use the Cairo episode to contextualize Mali inside Islamic and Mediterranean exchange rather than presenting West Africa as isolated.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.4 and 2.5"}, "sequence": 2, "topicCodes": ["2.4", "2.5"], "themeIds": ["GOV", "ECN", "CDI"], "examSkills": ["Causation", "Contextualization"], "causeStudyPointIds": ["apwh-u2-cairo-trans-saharan-gold-camel-caravans"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-nanjing-zheng-he-tributary-voyages"], "connectionNotes": {"apwh-u2-cairo-trans-saharan-gold-camel-caravans": "Trans-Saharan commerce made Mali's gold wealth visible in Cairo and supplied the resources displayed during Mansa Musa's pilgrimage.", "apwh-u2-nanjing-zheng-he-tributary-voyages": "Mansa Musa and Zheng He used conspicuous long-distance movement to display state wealth and strengthen diplomatic or religious standing."}, "unit": 2}, "apwh-u2-cairo-black-death-demographic-change": {"id": "apwh-u2-cairo-black-death-demographic-change", "locationNumber": "84", "mainEventKey": "world-event-84-0", "title": "Black Death and Demographic Change", "dateLabel": "1347–1351", "startYear": 1347, "endYear": 1351, "summary": "Plague traveled through commercial and military connections and caused severe mortality in Egypt and other densely connected regions.", "significance": "The pandemic reveals the biological cost of connectivity and changed labor supply, settlement, production, and state revenue across affected societies.", "keyPeople": [{"name": "Ibn Khaldun", "role": "A North African scholar who described plague-era population loss and its effects on cities, institutions, and political power."}], "keyTerms": [{"term": "Black Death", "explanation": "The fourteenth-century plague pandemic that spread across much of Afro-Eurasia."}, {"term": "demographic change", "explanation": "A major shift in population size, distribution, mortality, or age structure."}], "evidence": ["Plague reached Egypt through the connected Mediterranean and Red Sea commercial world during the late 1340s.", "Mass mortality reduced the number of workers and taxpayers and disrupted production and urban life."], "examConnection": "Use plague to explain an environmental consequence of exchange and trace the mechanism from network density to transmission and demographic change.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topic 2.6"}, "sequence": 3, "topicCodes": ["2.6"], "themeIds": ["ENV", "SIO"], "examSkills": ["Causation", "CCOT"], "causeStudyPointIds": ["apwh-u2-karakorum-pax-mongolica-protected-trade"], "effectStudyPointIds": [], "relatedStudyPointIds": ["apwh-u2-kilwa-crop-diffusion-environments"], "connectionNotes": {"apwh-u2-karakorum-pax-mongolica-protected-trade": "Denser and safer Eurasian movement also allowed plague-bearing hosts and vectors to travel farther through connected routes.", "apwh-u2-kilwa-crop-diffusion-environments": "Compare different biological consequences of connected networks: crop adoption could support food production and settlement, while epidemic pathogens caused mortality and disruption."}, "authorship": "teacher-revised", "revisionDate": "2026-10-25", "sourceNote": "Original AMSCO locator retained as legacy metadata, not a claim of verbatim verification. Revised wording is a teacher-authored synthesis; use revisionSources and the review ledger for verification.", "revisionSources": ["https://apcentral.collegeboard.org/media/pdf/ap-world-history-modern-course-and-exam-description-effective-fall-2026.pdf"], "unit": 2}, "apwh-u2-nanjing-treasure-fleet-technology-scale": {"id": "apwh-u2-nanjing-treasure-fleet-technology-scale", "locationNumber": "10", "mainEventKey": "world-event-10-3", "title": "Treasure-Fleet Technology and Scale", "dateLabel": "1405–1433", "startYear": 1405, "endYear": 1433, "summary": "Ming shipbuilding, navigational knowledge, and state logistics supported fleets far larger than ordinary merchant voyages.", "significance": "The fleet demonstrates how accumulated maritime technology produced exceptional reach when combined with taxation, labor, and direct imperial sponsorship.", "keyPeople": [{"name": "Ming shipbuilders and sailors", "role": "Built, supplied, navigated, and maintained the ships used in state-sponsored Indian Ocean expeditions."}], "keyTerms": [{"term": "treasure fleet", "explanation": "The large state-sponsored Ming fleets sent through the Indian Ocean under Zheng He."}, {"term": "watertight compartment", "explanation": "An internal ship division that limited flooding and protected cargo if part of the hull was damaged."}], "evidence": ["The expeditions used hundreds of vessels and tens of thousands of personnel at their greatest scale.", "Compasses, sternpost rudders, compartmentalized hulls, and extensive provisioning supported long-distance movement."], "examConnection": "Use the treasure fleets to explain how technology becomes historically significant when a state mobilizes resources to apply it at scale.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 1, "topicCodes": ["2.3", "2.7"], "themeIds": ["TEC", "GOV"], "examSkills": ["Causation"], "causeStudyPointIds": [], "effectStudyPointIds": ["apwh-u2-nanjing-zheng-he-tributary-voyages"], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-nanjing-zheng-he-tributary-voyages": "Large ships, navigational knowledge, and state resources made seven long-distance expeditions possible."}, "unit": 2}, "apwh-u2-nanjing-zheng-he-tributary-voyages": {"id": "apwh-u2-nanjing-zheng-he-tributary-voyages", "locationNumber": "10", "mainEventKey": "world-event-10-3", "title": "Zheng He's Tributary Voyages", "dateLabel": "1405–1433", "startYear": 1405, "endYear": 1433, "summary": "Zheng He led seven Ming expeditions that exchanged gifts, received envoys, and displayed imperial power across the Indian Ocean.", "significance": "The voyages intensified diplomatic and commercial contact without creating a territorial maritime empire like later European ventures.", "keyPeople": [{"name": "Zheng He", "role": "A Muslim eunuch admiral who commanded seven Ming voyages to Southeast Asia, South Asia, Arabia, and East Africa."}], "keyTerms": [{"term": "tribute system", "explanation": "A diplomatic framework in which foreign envoys offered gifts and received recognition and valuable returns from the Chinese court."}, {"term": "maritime diplomacy", "explanation": "The use of naval travel, gifts, envoys, and displays of force to manage relationships across the sea."}], "evidence": ["Seven voyages reached ports in Southeast Asia, South Asia, Arabia, and the East African coast.", "The fleets transported envoys and prestige goods and returned with tribute, including unfamiliar animals such as giraffes."], "examConnection": "Compare Zheng He with Mansa Musa as examples of rulers using long-distance movement and wealth to increase prestige without pursuing identical goals.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.5"}, "sequence": 2, "topicCodes": ["2.3", "2.5"], "themeIds": ["GOV", "CDI"], "examSkills": ["Causation", "Comparison"], "causeStudyPointIds": ["apwh-u2-nanjing-treasure-fleet-technology-scale"], "effectStudyPointIds": ["apwh-u2-nanjing-ming-maritime-retrenchment"], "relatedStudyPointIds": ["apwh-u2-cairo-mansa-musa-gold-shock"], "connectionNotes": {"apwh-u2-nanjing-treasure-fleet-technology-scale": "Large ships, navigational knowledge, and state resources made seven long-distance expeditions possible.", "apwh-u2-nanjing-ming-maritime-retrenchment": "The voyages demonstrated Ming reach but their cost and political purpose strengthened court arguments for ending them.", "apwh-u2-cairo-mansa-musa-gold-shock": "Mansa Musa and Zheng He used conspicuous long-distance movement to display state wealth and strengthen diplomatic or religious standing."}, "unit": 2}, "apwh-u2-nanjing-ming-maritime-retrenchment": {"id": "apwh-u2-nanjing-ming-maritime-retrenchment", "locationNumber": "10", "mainEventKey": "world-event-10-3", "title": "Ming Maritime Retrenchment", "dateLabel": "1433–1450", "startYear": 1433, "endYear": 1450, "summary": "After the final voyage, Ming rulers ended the treasure-fleet program and redirected resources toward domestic and northern priorities.", "significance": "Retrenchment shows that network participation depended on political choices: commercial demand continued even when direct state sponsorship declined.", "keyPeople": [{"name": "Ming court officials", "role": "Debated the cost and social value of maritime expeditions and supported policies that limited state-sponsored sailing."}], "keyTerms": [{"term": "maritime retrenchment", "explanation": "A deliberate reduction in state-sponsored overseas activity and naval investment."}, {"term": "Confucian bureaucracy", "explanation": "The scholar-official administration whose priorities often emphasized agrarian order and restrained imperial expenditure."}], "evidence": ["No new treasure-fleet expedition followed the seventh voyage ending in 1433.", "Court critics questioned the expense and value of the voyages while the state concentrated resources elsewhere."], "examConnection": "Use Ming retrenchment for continuity and change: private demand and Indian Ocean exchange continued, but the Chinese state changed its level of support.", "source": {"id": "amsco-apwh-u2", "locator": "AMSCO AP World History, Unit 2, Topics 2.3 and 2.7"}, "sequence": 3, "topicCodes": ["2.3", "2.7"], "themeIds": ["GOV", "ECN"], "examSkills": ["CCOT", "Causation"], "causeStudyPointIds": ["apwh-u2-nanjing-zheng-he-tributary-voyages"], "effectStudyPointIds": [], "relatedStudyPointIds": [], "connectionNotes": {"apwh-u2-nanjing-zheng-he-tributary-voyages": "The voyages demonstrated Ming reach but their cost and political purpose strengthened court arguments for ending them."}, "unit": 2}, "gender-song": {"id": "gender-song", "unit": 1, "title": "Song女性：家庭规范与foot binding", "dateLabel": "c. 1200–1279", "summary": "Song部分家庭将foot binding与地位、婚姻及审美相联系，限制了部分女性的行动。", "evidence": ["Song部分家庭将foot binding与地位、婚姻及审美相联系，限制了部分女性的行动。", "foot binding并非所有女性都采用；社会阶层、家庭资源及劳动方式会影响女性经历。"], "source": {"locator": "原 U1 Gender Divergence 讲稿；AMSCO U1 Topic 1.1；University of Missouri Museum of Anthropology补充核对。"}, "sourceUrls": ["https://anthromuseum.missouri.edu/e-exhibits/chinese-lotus-shoes"], "topicCodes": ["1.1", "1.7"]}, "gender-islam": {"id": "gender-islam", "unit": 1, "title": "Islamic societies女性：财产权与家庭规范", "dateLabel": "c. 1200–1450", "summary": "Islamic law传统承认女性可拥有财产，并通过婚资及继承取得资源。", "evidence": ["Islamic law传统承认女性可拥有财产，并通过婚资及继承取得资源。", "法律规范、地方习俗与实际执行并不完全相同；财产权不等于政治、婚姻或公共生活中的全面平等。"], "source": {"locator": "原 U1 Gender Divergence 讲稿；教师整理，参照 Oxford Handbook of Islam and Women 的婚姻与继承研究。"}, "sourceUrls": ["https://academic.oup.com/edited-volume/55356/chapter-abstract/430533035"], "topicCodes": ["1.2", "1.7"]}, "decline-song": {"id": "decline-song", "unit": 1, "title": "Southern Song Dynasty结束与Yuan Dynasty统治", "dateLabel": "1271–1279", "summary": "Khubilai Khan在1271年宣布建立Yuan Dynasty；1279年Mongol征服完成，Southern Song Dynasty结束。", "evidence": ["Khubilai Khan在1271年宣布建立Yuan Dynasty；1279年Mongol征服完成，Southern Song Dynasty结束。", "新的统治者重新组织治理；政权更替不意味着既有社会、文化及行政知识全部消失。"], "source": {"locator": "教师整理；Smithsonian National Museum of Asian Art, Yuan dynasty teaching resource。"}, "sourceUrls": ["https://asia-archive.si.edu/learn/for-educators/teaching-china-with-the-smithsonian/explore-by-dynasty/yuan-dynasty/"], "topicCodes": ["1.1", "1.7"]}, "decline-baghdad": {"id": "decline-baghdad", "unit": 1, "title": "Baghdad陷落与Abbasid统治结束", "dateLabel": "1258", "summary": "Hülegü率Mongol军队于1258年攻陷Baghdad，终结当地Abbasid哈里发统治。", "evidence": ["Hülegü率Mongol军队于1258年攻陷Baghdad，终结当地Abbasid哈里发统治。", "这一结果应放在Mongol扩张与区域政治变化中解释；不能只归因于城市维护费用，也不能说Islamic文明至此终结。"], "source": {"locator": "原 U1 Why States Decline 讲稿，经 The Metropolitan Museum of Art 伊儿汗时期专题核对；教师整理。"}, "sourceUrls": ["https://www.metmuseum.org/essays/the-art-of-the-ilkhanid-period-1256-1353"], "topicCodes": ["1.2", "1.7"]}};
